<?php
namespace App\Http\Controllers; use App\Models\{PerformanceReport,User};use App\Services\PerformanceReportService;use Illuminate\Http\Request;
class PerformanceController extends Controller { public function index(PerformanceReportService $s){$metrics=$s->metrics();return view('performance.index',compact('metrics'));} public function create(){return view('performance.form',['teachers'=>User::teachers()->get()]);} public function store(Request $r,PerformanceReportService $s){$d=$r->validate(['title'=>'required|string|max:255','period'=>'required|string|max:100','teacher_id'=>'nullable|exists:users,id','date_from'=>'nullable|date','date_to'=>'nullable|date|after_or_equal:date_from']);$teacher=!empty($d['teacher_id'])?User::teachers()->findOrFail($d['teacher_id']):null;$metrics=$s->metrics($teacher,$d['date_from']??null,$d['date_to']??null);if(!$metrics['report_count']&&!collect($metrics['teachers'])->sum('evaluations')&&!collect($metrics['teachers'])->sum('feedback'))return back()->withInput()->withErrors(['teacher_id'=>'No data available for the selected scope.']);$report=PerformanceReport::create($d+['generated_by'=>$r->user()->id,'content'=>$metrics,'generated_at'=>now()]);return redirect()->route('performance.show',$report)->with('success','Performance report generated successfully.');} public function show(PerformanceReport $report){return view('performance.show',compact('report'));} public function download(PerformanceReport $report){return response()->view('performance.print',compact('report'))->header('Content-Disposition','attachment; filename="performance-report-'.$report->id.'.html"');}}
